// ==== Gafas: reaccionan a las cejas, la boca y la sonrisa ====
//
// Cada funcion se llama sola cuando ocurre ese gesto. Cambia lo que hay dentro
// o deja la funcion vacia si no la necesitas.
//   this  -> el objeto que tiene el script (las gafas)
//   face  -> la cara, con valores de 0 a 1: face.browRaise, face.jawOpen,
//            face.smile, face.blink y face.blendshapes.<nombre>
// En el editor solo se ejecutan start y update (alli `face` no existe).

let baseY = 0;
let baseScale = 1;
let lift = 0;

// ---- Ciclo de vida -------------------------------------------------------

function start() {
	baseY = this.position.y;
	baseScale = this.scale.x;
}

function update(event) {
	// Cada fotograma. event.time y event.delta en milisegundos.
}

// ---- Cara ----------------------------------------------------------------

function faceFound(event) {
	// La cara aparece en la camara.
}

function faceLost(event) {
	// La cara sale de la camara.
}

// Cada fotograma con cara: las gafas suben poco a poco al levantar las cejas.
function faceUpdate(event) {
	lift += (face.browRaise - lift) * 0.3;
	this.position.y = baseY + lift * 0.15;
}

// ---- Cejas ---------------------------------------------------------------

// Cejas arriba (cara de sorpresa): las gafas se inclinan hacia atras.
function browRaise(event) {
	this.rotation.x = -0.25;
}

// Cejas abajo: vuelven a su sitio.
function browLower(event) {
	this.rotation.x = 0;
}

// ---- Boca ----------------------------------------------------------------

// Abrir la boca: las gafas desaparecen.
function mouthOpen(event) {
	this.visible = false;
}

function mouthClose(event) {
	this.visible = true;
}

// ---- Sonrisa -------------------------------------------------------------

// Sonreir: las gafas crecen.
function smileStart(event) {
	this.scale.setScalar(baseScale * 1.3);
}

function smileEnd(event) {
	this.scale.setScalar(baseScale);
}

// ---- Ojos ----------------------------------------------------------------

function blink(event) {
	// Parpadeo. Idea: this.rotation.z = 0.1;
}

function blinkEnd(event) {
	// Los ojos se vuelven a abrir. Idea: this.rotation.z = 0;
}

