// ==== Nariz: crece con la boca, cambia de color y brilla al parpadear ====
//
// Cada funcion se llama sola cuando ocurre ese gesto. Cambia lo que hay dentro
// o deja la funcion vacia si no la necesitas.
//   this  -> el objeto que tiene el script (la esfera)
//   face  -> la cara, con valores de 0 a 1: face.jawOpen, face.smile,
//            face.blink, face.browRaise y face.blendshapes.<nombre>
// En el editor solo se ejecutan start y update (alli `face` no existe).

let baseScale = 1;
let baseColor = 0xffffff;

// ---- Ciclo de vida -------------------------------------------------------

function start() {
	baseScale = this.scale.x;
	baseColor = this.material.color.getHex();
}

function update(event) {
	// Cada fotograma. event.time y event.delta en milisegundos.
}

// ---- Cara ----------------------------------------------------------------

function faceFound(event) {
	// La cara aparece en la camara.
}

function faceLost(event) {
	// La cara sale de la camara.
}

// Cada fotograma con cara: la nariz crece segun lo abierta que este la boca.
function faceUpdate(event) {
	this.scale.setScalar(baseScale * (1 + face.jawOpen * 1.5));
}

// ---- Boca ----------------------------------------------------------------

// Boca abierta: la nariz se vuelve amarilla.
function mouthOpen(event) {
	this.material.color.set(0xffd43b);
}

function mouthClose(event) {
	this.material.color.setHex(baseColor);
}

// ---- Ojos ----------------------------------------------------------------

// Parpadeo: la nariz brilla mientras los ojos estan cerrados.
function blink(event) {
	this.material.emissive.set(0xffffff);
	this.material.emissiveIntensity = 0.6;
}

function blinkEnd(event) {
	this.material.emissive.set(0x000000);
}

// ---- Sonrisa -------------------------------------------------------------

function smileStart(event) {
	// Empieza a sonreir. Idea: this.material.color.set(0xff69b4);
}

function smileEnd(event) {
	// Deja de sonreir. Idea: this.material.color.setHex(baseColor);
}

// ---- Cejas ---------------------------------------------------------------

function browRaise(event) {
	// Cejas arriba. Idea: this.position.y += 0.05;
}

function browLower(event) {
	// Cejas abajo. Idea: this.position.y -= 0.05;
}

