// ==== Hacha: al abrir la boca se clava en la frente (con sonido) ====
//
// La pose que dejaste en el editor es la pose FINAL (hacha clavada).
// El script la guarda, esconde el hacha, y al abrir la boca la lanza
// desde arriba hasta esa pose con un pequeño rebote al impactar.

// ---- Ajustes ----
const DURACION      = 0.22;                              // segundos del golpe (0.15 = más seco)
const DESDE_POS     = new THREE.Vector3(0, 0.6, 0.5);    // de dónde viene (offset respecto a la pose final)
const DESDE_ROT     = new THREE.Euler(-1.3, 0, 0.4);     // giro extra al inicio (hacha levantada)
const ESCALA_INICIO = 1.6;                               // empieza más grande y se encoge al impactar
const VIBRACION     = 0.12;                              // fuerza del temblor al clavarse

// ---- Sonido ----
const SONIDO  = 'https://mascara-swart.vercel.app/assets/musica/hacha.mp3.mp3';   // ruta del audio (renombra tu archivo a hacha.mp3)
const VOLUMEN = 1.0;                         // 0 a 1

// ---- Interno ----
let hacha = null;
let audio = null;
let estado = 'oculta';   // oculta -> golpeando -> clavada
let t = 0, tImpacto = 0;

const posFinal  = new THREE.Vector3();
const rotFinal  = new THREE.Euler();
const escalaFin = new THREE.Vector3();

const easeIn = x => x * x * x;   // acelera como un golpe

function sonarImpacto() {
	if (!audio) return;
	audio.currentTime = 0;               // reinicia si ya estaba sonando
	audio.play().catch(() => {});        // ignora el error si el navegador lo bloquea
}

function reiniciar() {
	estado = 'oculta';
	hacha.visible = false;
	hacha.position.copy(posFinal);
	hacha.rotation.copy(rotFinal);
	hacha.scale.copy(escalaFin);
}

function golpear() {
	if (estado !== 'oculta') return;
	estado = 'golpeando';
	t = 0;
	hacha.visible = true;
}

// ---- Ciclo de vida ----
function start() {
	hacha = this;
	posFinal.copy(hacha.position);
	rotFinal.copy(hacha.rotation);
	escalaFin.copy(hacha.scale);

	audio = new Audio(SONIDO);
	audio.volume = VOLUMEN;
	audio.preload = 'auto';

	reiniciar();
}

function update(event) {
	if (!hacha) return;
	const dt = event.delta / 1000;

	if (estado === 'golpeando') {
		t += dt / DURACION;
		const k = easeIn(Math.min(t, 1));

		hacha.position.copy(posFinal).addScaledVector(DESDE_POS, 1 - k);
		hacha.rotation.set(
			rotFinal.x + DESDE_ROT.x * (1 - k),
			rotFinal.y + DESDE_ROT.y * (1 - k),
			rotFinal.z + DESDE_ROT.z * (1 - k)
		);
		hacha.scale.copy(escalaFin).multiplyScalar(1 + (ESCALA_INICIO - 1) * (1 - k));

		if (t >= 1) {
			estado = 'clavada';
			tImpacto = 0;
			sonarImpacto();   // suena justo al clavarse
		}
	}

	if (estado === 'clavada') {
		// temblor amortiguado al impactar
		tImpacto += dt;
		const sacudida = Math.exp(-tImpacto * 14) * Math.sin(tImpacto * 60) * VIBRACION;
		hacha.position.copy(posFinal);
		hacha.rotation.set(rotFinal.x, rotFinal.y, rotFinal.z + sacudida);
		hacha.scale.copy(escalaFin);
	}
}

// ---- Cara ----
function faceLost(event) {
	reiniciar();   // si la cara sale de cámara, el hacha desaparece
}

// ---- Boca ----
function mouthOpen(event) {
	golpear();
}

function mouthClose(event) {
	reiniciar();   // al cerrar la boca, se resetea y queda lista para otro golpe
}

