// ==== Beso: suena al hacer trompita ====
const SONIDO  = 'assets/musica/beso.mp3';
const VOLUMEN = 1.0;

let audio = null;

function start() {
	audio = new Audio(SONIDO);
	audio.volume = VOLUMEN;
	audio.preload = 'auto';
	audio.addEventListener('error', () => console.warn('[beso] no cargó:', audio.src));
}

function update(event) {}

// Desbloquea el audio con el primer toque/clic en la página
function pointerdown(event) {
	if (!audio) return;
	audio.muted = true;
	audio.play().then(() => {
		audio.pause();
		audio.currentTime = 0;
		audio.muted = false;
	}).catch(() => { audio.muted = false; });
}

function kissStart(event) {
	if (!audio) return;
	audio.currentTime = 0;
	audio.play().catch(e => console.warn('[beso] no pudo sonar:', e.name));
}

function kissEnd(event) {}
